import React, { useCallback, useEffect, useRef, useState } from "react";
import { IconButton, InputBase, Paper } from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import FilterAltIcon from "@mui/icons-material/FilterAlt";
import { getBox, getPokeData } from "../utils";
import { useURLParams } from "../hooks/useURLParams";

export function SearchBar({ setData, setLoading, onToggleFilters }) {
  const { usernames: usernamesParam, setUsernames: setUsernamesParam } =
    useURLParams();
  const [usernames, setUsernames] = useState(usernamesParam);

  const fetchData = useCallback(
    async (value) => {
      setData([]);
      setLoading(true);
      const boxData = await getBox(value);
      const results = await getPokeData(boxData);
      setData(results);
      setLoading(false);
    },
    [setData, setLoading],
  );

  const didAutoSubmitRef = useRef(false);
  useEffect(() => {
    setUsernames(usernamesParam);
    if (didAutoSubmitRef.current) return;
    if (!usernamesParam) return;

    didAutoSubmitRef.current = true;
    fetchData(usernamesParam);
  }, [usernamesParam, fetchData]);

  const onSubmit = (e) => {
    e?.preventDefault();
    setUsernamesParam(usernames);
    didAutoSubmitRef.current = true;
    fetchData(usernames);
  };

  return (
    <Paper
      component="form"
      onSubmit={onSubmit}
      sx={{ p: "2px 4px", display: "flex", alignItems: "center" }}
    >
      <IconButton
        type="button"
        sx={{ p: "10px" }}
        aria-label="filter"
        onClick={onToggleFilters}
      >
        <FilterAltIcon />
      </IconButton>
      <InputBase
        sx={{ ml: 1, flex: 1 }}
        placeholder="Enter username"
        inputProps={{ "aria-label": "enter username" }}
        value={usernames}
        onChange={(e) => setUsernames(e.target.value)}
      />
      <IconButton
        type="submit"
        sx={{ p: "10px" }}
        aria-label="search"
        color="primary"
      >
        <SearchIcon />
      </IconButton>
    </Paper>
  );
}
