import { useEffect, useState } from "react";
import { Box, Chip, Badge, Typography, Tooltip, Paper } from "@mui/material";
import ArrowDownwardIcon from "@mui/icons-material/ArrowDownward";
import ArrowUpwardIcon from "@mui/icons-material/ArrowUpward";
import { useURLParams } from "../hooks/useURLParams";

const FIELD_CONFIGS = [
  { field: "percentage", label: "Percentage" },
  { field: "rating", label: "Rating" },
  { field: "baseRating", label: "Base Rating" },
  { field: "name", label: "Name" },
  { field: "level", label: "Level" },
  {
    field: "total",
    label: "Count",
  },
  {
    field: "rarity.total",
    label: "Rarity",
  },
];

const FIELD_KEYS = new Set(FIELD_CONFIGS.map((c) => c.field));

export default function SortBuilder() {
  const { sort: sortParam, setSort: setSortParam } = useURLParams();
  const [sorts, setSorts] = useState(sortParam);

  useEffect(() => {
    setSorts(sortParam);
  }, [sortParam]);

  const toggleSort = (field) => {
    let next = [...sorts];

    const existing = sorts.find((s) => s.field === field);

    if (!existing) {
      next.push({ field, direction: 1 });
    } else if (existing.direction === 1) {
      next = next.map((s) => (s.field === field ? { ...s, direction: -1 } : s));
    } else {
      next = next.filter((s) => s.field !== field);
    }

    setSortParam(next);
  };

  const orderedFieldConfigs = [
    ...sorts
      .filter((s) => FIELD_KEYS.has(s.field))
      .map((s) => FIELD_CONFIGS.find((c) => c.field === s.field))
      .filter(Boolean),
    ...FIELD_CONFIGS.filter((c) => !sorts.some((s) => s.field === c.field)),
  ];

  return (
    <Paper sx={{ p: 2, minWidth: 0 }}>
      <Box
        sx={{
          display: "flex",
          alignItems: "flex-start",
          gap: 1,
          minWidth: 0,
          width: "100%",
        }}
      >
        <Typography
          component="span"
          variant="body2"
          sx={{ flexShrink: 0, whiteSpace: "nowrap", lineHeight: "32px" }}
        >
          Sort by:
        </Typography>
        <Box
          sx={{
            display: "flex",
            flex: 1,
            minWidth: 0,
            flexWrap: "wrap",
            alignItems: "center",
            alignContent: "flex-start",
            gap: 1,
            rowGap: 1,
          }}
        >
          {orderedFieldConfigs.map((config) => {
            const { field, label, hint } = config;
            const index = sorts.findIndex((s) => s.field === field);
            const active = index !== -1;
            const sort = sorts[index];

            const chip = (
              <Chip
                label={
                  active ? (
                    <Box
                      component="span"
                      sx={{
                        display: "inline-flex",
                        alignItems: "center",
                        gap: 0.5,
                        pr: 0.25,
                      }}
                    >
                      {label}
                      {sort.direction === 1 ? (
                        <ArrowUpwardIcon
                          sx={{ fontSize: 20, flexShrink: 0 }}
                          aria-hidden
                        />
                      ) : (
                        <ArrowDownwardIcon
                          sx={{ fontSize: 20, flexShrink: 0 }}
                          aria-hidden
                        />
                      )}
                    </Box>
                  ) : (
                    label
                  )
                }
                color={active ? "primary" : "default"}
                variant={active ? "filled" : "outlined"}
                onClick={() => toggleSort(field)}
              />
            );

            const withBadge = active ? (
              <Badge badgeContent={index + 1} color="secondary">
                {chip}
              </Badge>
            ) : (
              chip
            );

            const node = hint ? (
              <Tooltip title={hint} placement="top" arrow>
                <Box
                  component="span"
                  sx={{ display: "inline-flex", verticalAlign: "middle" }}
                >
                  {withBadge}
                </Box>
              </Tooltip>
            ) : (
              withBadge
            );

            return (
              <Box
                key={field}
                component="span"
                sx={{ display: "inline-flex", verticalAlign: "middle" }}
              >
                {node}
              </Box>
            );
          })}
        </Box>
      </Box>
    </Paper>
  );
}
