import React, { useCallback, useState } from "react";
import { IconButton, InputBase, Paper } from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import FilterAltIcon from "@mui/icons-material/FilterAlt";
import { getPokeData, parseBoxInput } from "../utils";

export function ManualInput({ setData, setLoading, onToggleFilters }) {
  const [value, setValue] = useState("");

  const fetchData = useCallback(
    async (value) => {
      setData([]);
      setLoading(true);
      const pokemonList = parseBoxInput(value);
      const results = await getPokeData(pokemonList);
      setData(results);
      setLoading(false);
    },
    [setData, setLoading],
  );

  const onSubmit = (e) => {
    e?.preventDefault();
    fetchData(value);
  };

  return (
    <Paper
      component="form"
      onSubmit={onSubmit}
      sx={{ p: "2px 4px", display: "flex", alignItems: "center" }}
    >
      <IconButton
        type="button"
        sx={{ p: "10px" }}
        aria-label="filter"
        onClick={onToggleFilters}
      >
        <FilterAltIcon />
      </IconButton>
      <InputBase
        sx={{
          ml: 1,
          flex: 1,
          "& .MuiInputBase-input": {
            resize: "vertical",
          },
        }}
        placeholder="Enter details"
        inputProps={{ "aria-label": "enter box details" }}
        value={value}
        multiline
        rows={3}
        onChange={(e) => setValue(e.target.value)}
      />
      <IconButton
        type="submit"
        sx={{ p: "10px" }}
        aria-label="search"
        color="primary"
      >
        <SearchIcon />
      </IconButton>
    </Paper>
  );
}
