import { ShortVariant, Variant } from "./constants";
import get from "lodash/get";
import pokemonTags from "./pokemon_data.json";

/**
 * @param {string} str
 * @returns {string}
 */
export function normalizePokemonIdentifier(str) {
  return String(str)
    .replace(/[^a-zA-Z0-9]/g, "")
    .toLowerCase();
}

/**
 * Converts a string like "5.5k" or "2.5m" into an integer.
 * Supports k (thousand) and m (million).
 *
 * @param {string | number} value
 * @returns {number}
 */
export function parseNumber(value) {
  if (value === null || value === undefined) return 0;
  if (typeof value === "number") return Math.round(value);

  const str = value.toString().trim().toLowerCase();
  const match = str.match(/^([\d.]+)\s*([km]?)$/);

  if (!match) {
    const num = Number(str);
    return Number.isNaN(num) ? 0 : Math.round(num);
  }

  const number = parseFloat(match[1]);
  const suffix = match[2];

  const multipliers = {
    k: 1_000,
    m: 1_000_000,
  };

  return Math.round(number * (multipliers[suffix] || 1));
}

/**
 * Converts an integer into abbreviated format like "5.5k" or "2.5m".
 *
 * @param {number} value
 * @param {number} sig
 * @returns {string}
 */
export function formatNumber(value, sig = 2) {
  if (!value || isNaN(value)) return "N/A";

  const parsed = parseInt(value, 10);

  if (parsed >= 1_000_000) {
    const num = parsed / 1_000_000;
    return `${num.toFixed(sig)}M`;
  }

  if (parsed >= 1_000) {
    const num = parsed / 1_000;
    return `${num.toFixed(sig)}K`;
  }

  return `${value}`;
}

function parseBoxItem(item) {
  const result = {};
  // normalize quantifier
  item = item
    .replace(/\*/g, "x")
    .replace(/\bx (\d+)/gi, "x$1") // x 5 -> x5
    .replace(/\b(\d+) x\b/gi, "$1x"); // 5 x -> 5x

  const tokens = item.trim().split(/\s+/);
  let i = 0;

  while (i < tokens.length) {
    const t = tokens[i];
    let m;
    // 2x
    if ((m = t.match(/^(\d+)x$/))) {
      result.count1 = Number(m[1]);
    }
    // x1
    else if ((m = t.match(/^x(\d+)$/))) {
      result.count2 = Number(m[1]);
    }
    // gender
    else if (/^[mf]$/i.test(t)) {
      result.gender = t.toLowerCase();
    }
    // Level
    else if (/^level:?$/i.test(t) && /^[\d,]+$/.test(tokens[i + 1])) {
      result.level = tokens[i + 1];
      i++;
    }
    // first unknown token becomes name
    else if (!result.name) {
      const variant = Object.entries(ShortVariant).find(
        ([k, v]) =>
          t.toLowerCase().startsWith(k.toLowerCase()) ||
          t.toLowerCase().startsWith(v.toLowerCase()),
      );
      if (variant) {
        result.name = t
          .toLowerCase()
          .replace(variant[1].toLowerCase(), variant[0].toLowerCase());
      }
    }

    i++;
  }

  return result;
}

export function parseBoxInput(value) {
  const pokemonList = [];
  const items = value
    .split(/[\n,]+/)
    .map((line) => line.trim())
    .filter(Boolean);

  items.forEach((item) => {
    const itemData = parseBoxItem(item);
    if (itemData.name) {
      const {
        count1 = "1",
        name,
        gender = "",
        level = "5",
        count2 = "1",
      } = itemData;
      const count = parseInt(count1) * parseInt(count2);
      pokemonList.push({
        name: name.trim(),
        gender: gender.trim(),
        level: parseInt(level.replace(/,/g, "")), // Remove commas for numeric parsing
        count,
      });
    }
  });

  return pokemonList;
}

/**
 * @typedef {Object} BaseInfo
 * @property {string} name
 * @property {string} gender
 * @property {number} level
 * @property {number} count
 */

/**
 *
 * @param {string} userString
 * @returns {Promise<Array<BaseInfo>>}
 */
export const getBox = async (userString) => {
  const prefixes = Object.values(Variant);
  // Parse and clean usernames
  const users = userString
    .split(",")
    .map((user) => user.trim())
    .filter(Boolean);

  // Fetch data concurrently
  const result = await Promise.allSettled(
    users.map(async (user) => {
      try {
        const response = await fetch(
          `https://pokemoncreed.net/ajax/box.php?user=${user}`,
        );

        if (!response.ok) {
          throw new Error(`Failed to fetch data for ${user}`);
        }

        const res = await response.json();
        if (!res.success) {
          console.error(`User ${user} not found.`);
        }

        return res?.data?.pokemon
          .filter((p) =>
            prefixes.some((v) =>
              p.name.toLowerCase().startsWith(v.toLowerCase()),
            ),
          )
          .map((p) => {
            const level = parseNumber(p.level);
            const gender =
              p.gender.toLowerCase() === "m"
                ? "male"
                : p.gender.toLowerCase() === "f"
                  ? "female"
                  : "ungendered";

            return {
              name: p.name,
              count: 1,
              gender,
              level,
            };
          });
      } catch (error) {
        console.error(`Error fetching data for ${user}:`, error.message);
      }
    }),
  );

  return result.flatMap((r) => (r.status === "fulfilled" ? r.value : []));
};

/**
 * @typedef {BaseInfo} DetailedInfo
 * @property {{male: number, female: number, ungendered: number, total: number}} rarity
 * @property {number} baseRating
 * @property {number} rating
 * @property {number} percentage
 * @property {string} id
 * @property {string} variant
 * @property {string} pokemon
 * @property {number} male
 * @property {number} female
 * @property {number} ungendered
 * @property {number} total
 * @property {number} count
 * @property {Array<string>} tags
 */

/**
 * Enriches each Pokémon with Pokédex data.
 * Uses a cache keyed by Pokémon name to reduce API calls.
 *
 * @param {Array<BaseInfo>} pokemonList
 * @returns {Promise<Array<DetailedInfo>>}
 */
export async function getPokeData(pokemonList) {
  const prefixes = Object.values(Variant);
  // Cache keyed by Pokémon name
  const cache = new Map();
  const unique = [...new Set(pokemonList.map((p) => p.name.toLowerCase()))];
  const fetchData = unique.map(async (input) => {
    try {
      const response = await fetch(
        `https://pokemoncreed.net/ajax/pokedex.php?pokemon=${encodeURIComponent(
          input.replace(" ", "_"),
        )}`,
      );
      if (!response.ok) {
        throw new Error(`Failed to fetch Pokédex data for ${input}`);
      }

      const data = await response.json();

      if (!data.success) {
        throw new Error(`Failed to fetch Pokédex data for ${input}`);
      }

      const { rating, rarity, name } = data;
      cache.set(input, {
        name,
        rarity,
        rating,
      });
    } catch (error) {
      console.error(`Error fetching Pokédex data for ${input}:`, error.message);
      cache.set(input, null);
    }
  });
  await Promise.all(fetchData);

  const resultMap = new Map();
  pokemonList.forEach((pokemon, id) => {
    const { name: input, gender, level, count } = pokemon;
    const data = cache.get(input.toLowerCase());
    if (!data) {
      return;
    }

    const { rating, rarity, name } = data;

    const variant = prefixes.find((p) => name.startsWith(p));
    const species = name.slice(variant.length);
    const tags = pokemonTags[normalizePokemonIdentifier(species)] ?? [];

    const info = {
      id: `${id}`,
      variant,
      pokemon: species,
      name,
      level,
      gender,
      baseRating: parseNumber(rating),
      rarity: {
        male: parseNumber(rarity?.male),
        female: parseNumber(rarity?.female),
        ungendered: parseNumber(rarity?.ungendered),
        total: parseNumber(rarity?.total),
      },
      male: 0,
      female: 0,
      ungendered: 0,
      count: 0,
      tags,
    };

    if (!resultMap.has(name)) {
      resultMap.set(name, new Map());
    }

    if (!resultMap.get(name).has(level)) {
      resultMap.get(name).set(level, info);
    }

    resultMap.get(name).get(level).count += count ?? 1;
    resultMap.get(name).get(level)[gender] += count ?? 1;
  });

  // Merge cached Pokédex data with the original Pokémon map
  const result = [];
  for (const group of resultMap.values()) {
    const values = Array.from(group.values());
    const total = values.reduce((acc, data) => acc + data.count, 0);
    const percentage = (total / values[0].rarity.total) * 100;
    for (const poke of values) {
      result.push({
        ...poke,
        rating:
          poke.baseRating * (poke.level > 5 ? 0.8 : poke.level === 5 ? 1 : 3),
        total,
        percentage,
      });
    }
  }

  return result;
}

/**
 * Produces a short, deterministic digest of a result set. Used to validate
 * that a saved per-result state (e.g. selected items in the URL) still
 * matches the currently loaded data.
 *
 * @param {Array<DetailedInfo>} data
 * @returns {string}
 */
export function digestResults(data) {
  if (!data?.length) return "";
  const sig = data
    .map((p) => `${p.id}|${p.name}|${p.level}|${p.count}`)
    .sort()
    .join(",");
  let h = 0x811c9dc5;
  for (let i = 0; i < sig.length; i++) {
    h ^= sig.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(36);
}

/**
 *
 * @param {Array<DetailedInfo>} data
 * @param {Record<string, {operator: string, value: string | number | Array}>} filters
 * @param {Array<{field: string, direction: -1 | 1}>} sort
 * @returns {Array<DetailedInfo>}
 */
export function applyParams(data, filters, sort) {
  const filtered = data.filter((item) => {
    const results = filters.map((f) => {
      if (!f.field || !f.operator) return true;

      const value = get(item, f.field);
      const query = f.value;

      switch (f.operator) {
        case "contains":
          return value?.toLowerCase().includes(query?.toLowerCase());
        case "not_contains":
          return !value?.toLowerCase().includes(query?.toLowerCase());
        case "lt":
          return value < query;
        case "lte":
          return value <= query;
        case "eq":
          return value === query;
        case "neq":
          return value !== query;
        case "gte":
          return value >= query;
        case "gt":
          return value > query;
        case "in":
          return value instanceof Array
            ? value.some((v) => query?.includes(v))
            : query?.includes(value);
        case "not_in":
          return value instanceof Array
            ? value.every((v) => !query?.includes(v))
            : !query?.includes(value);
        default:
          return true;
      }
    });

    return results.every(Boolean);
  });

  if (!sort.length)
    sort = [
      { field: "baseRating", direction: -1 },
      { field: "name", direction: -1 },
      { field: "level", direction: -1 },
    ];
  const sorted = filtered.sort((a, b) => {
    for (const rule of sort) {
      const { field, direction } = rule;

      const aVal = get(a, field);
      const bVal = get(b, field);

      // handle null/undefined (push to end)
      if (aVal == null && bVal == null) continue;
      if (aVal == null) return 1;
      if (bVal == null) return -1;

      if (aVal < bVal) return -1 * direction;
      if (aVal > bVal) return 1 * direction;
      // if equal → move to next rule
    }

    return 0;
  });

  return sorted;
}
