import {
  Box,
  Select,
  MenuItem,
  TextField,
  Button,
  Chip,
  IconButton,
  Tooltip,
  Paper,
  Divider,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import RemoveIcon from "@mui/icons-material/Remove";
import RestartAltIcon from "@mui/icons-material/RestartAlt";
import { v4 as uuid } from "uuid";
import { useEffect, useState } from "react";
import { filterConfigs, OPERATORS } from "../constants";
import { useURLParams } from "../hooks/useURLParams";

function getOperators(config) {
  if (!config) return [];
  const all = OPERATORS[config.type] || [];
  if (!config.operators) return all;
  return all.filter((op) => config.operators.includes(op.value));
}

export function FilterBuilder({ open = false }) {
  const { filters: filtersParam, setFilters: setFiltersParam } = useURLParams();
  const [filters, setFilters] = useState(filtersParam);

  useEffect(() => {
    setFilters(filtersParam);
  }, [filtersParam]);

  if (!open) return null;

  const updateFilter = (id, patch) => {
    setFilters((filters) =>
      filters.map((f) => (f.id === id ? { ...f, ...patch } : f)),
    );
  };

  const addFilter = () => {
    setFilters((filters) => [...filters, { id: uuid() }]);
  };

  const removeFilter = (id) => {
    handleSubmit(filters.filter((f) => f.id !== id));
  };

  const reset = () => {
    handleSubmit([]);
  };

  const handleSubmit = (value) => {
    setFilters(value ?? filters);
    setFiltersParam(value ?? filters);
  };

  return (
    <Paper
      sx={{
        // mt: 2,
        p: 1,
        display: "flex",
        flexDirection: "column",
        gap: 1,
      }}
    >
      <Divider />
      {filters.map((f) => {
        const config = filterConfigs.find((c) => c.key === f.field);
        const operators = getOperators(config);

        return (
          <Box key={f.id} display="flex" alignItems="flex-start">
            <Box
              display="flex"
              gap={1}
              flex={1}
              minWidth={0}
              alignItems="center"
              flexWrap="wrap"
            >
              {/* field */}
              <Select
                size="small"
                value={f.field || ""}
                onChange={(e) => {
                  const config = filterConfigs.find(
                    (c) => c.key === e.target.value,
                  );
                  const operators = getOperators(config);
                  updateFilter(f.id, {
                    field: e.target.value,
                    operator:
                      operators.length === 1 ? operators[0].value : undefined,
                    value: undefined,
                  });
                }}
                sx={{ width: 140 }}
              >
                {filterConfigs.map((c) => (
                  <MenuItem key={c.key} value={c.key}>
                    {c.label}
                  </MenuItem>
                ))}
              </Select>

              {/* operator */}
              {operators.length > 1 && (
                <Select
                  size="small"
                  value={f.operator || ""}
                  onChange={(e) =>
                    updateFilter(f.id, { operator: e.target.value })
                  }
                  onBlur={() => f.value && handleSubmit()}
                  sx={{ width: 140 }}
                >
                  {operators.map((op) => (
                    <MenuItem key={op.value} value={op.value}>
                      {op.label}
                    </MenuItem>
                  ))}
                </Select>
              )}

              {/* value */}
              {f.field && f.operator && (
                <Box sx={{ flex: "1 1 100px" }}>
                  {config.type === "string" && (
                    <TextField
                      fullWidth
                      size="small"
                      value={f.value || ""}
                      onChange={(e) =>
                        updateFilter(f.id, { value: e.target.value })
                      }
                      onBlur={() => handleSubmit()}
                    />
                  )}

                  {config.type === "number" && (
                    <TextField
                      fullWidth
                      size="small"
                      type="number"
                      value={f.value ?? ""}
                      onChange={(e) =>
                        updateFilter(f.id, {
                          value: Number(e.target.value),
                        })
                      }
                      onBlur={() => handleSubmit()}
                    />
                  )}

                  {config.type === "enum" && (
                    <Select
                      fullWidth
                      multiple
                      size="small"
                      value={f.value || []}
                      onChange={(e) =>
                        updateFilter(f.id, { value: e.target.value ?? [] })
                      }
                      onClose={() => handleSubmit()}
                      renderValue={(selected) => (
                        <Box
                          sx={{ display: "flex", gap: 0.5, flexWrap: "wrap" }}
                        >
                          {selected.map((v) => (
                            <Chip key={v} label={v} />
                          ))}
                        </Box>
                      )}
                    >
                      {config.options.map((opt) => (
                        <MenuItem key={opt} value={opt}>
                          {opt}
                        </MenuItem>
                      ))}
                    </Select>
                  )}
                </Box>
              )}
            </Box>

            <Tooltip title="Remove filter">
              <IconButton
                size="small"
                aria-label="remove filter"
                onClick={() => removeFilter(f.id)}
              >
                <RemoveIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          </Box>
        );
      })}

      <Box
        sx={{
          display: "flex",
          alignItems: "center",
          "& .MuiButton-root": {
            lineHeight: 1.4,
            minWidth: "unset",
            width: "auto",
            height: "auto",
            px: 1.5,
            py: 0.75,
          },
          "& .MuiButton-startIcon": { mr: 0.75 },
        }}
      >
        <Button
          size="small"
          variant="text"
          startIcon={<AddIcon fontSize="small" />}
          onClick={addFilter}
        >
          Add filter
        </Button>
        <Box sx={{ flex: 1 }} />
        <Button
          size="small"
          variant="text"
          color="inherit"
          startIcon={<RestartAltIcon fontSize="small" />}
          onClick={reset}
          disabled={filters.length === 0}
        >
          Reset
        </Button>
      </Box>
    </Paper>
  );
}
