import "./App.css";
import React, { useMemo, useRef, useState } from "react";
import {
  Box,
  TextField,
  Typography,
  Stack,
  CircularProgress,
  Paper,
  Table,
  TableBody,
  TableCell,
  Tooltip,
  TableContainer,
  TableHead,
  TableRow,
  Divider,
  Chip,
} from "@mui/material";
import { applyParams, formatNumber } from "./utils";
import { SearchBar } from "./components/searchbar";
import { FilterBuilder } from "./components/filter";
import { useURLParams } from "./hooks/useURLParams";
import PokeChart from "./components/chart";
import SortBuilder from "./components/sort";
import IconTabs, { TabPanel } from "./components/icontabs";
import { ManualInput } from "./components/manualinput";

function App() {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState([]);
  const { filters, sort, selected, setSelected } = useURLParams(data);
  const [editingKey, setEditingKey] = useState(null);
  const [filtersOpen, setFiltersOpen] = useState(filters.length > 0);
  const [tab, setTab] = useState(0);
  const resultsRef = useRef(null);

  const results = useMemo(
    () => applyParams(data, filters, sort),
    [data, filters, sort],
  );

  const totalRating = useMemo(() => {
    return results.reduce((acc, p) => acc + p.rating * p.count, 0);
  }, [results]);

  const selectedRows = useMemo(
    () => results.filter((p) => selected.has(p.id)),
    [results, selected],
  );

  const totalSelectedValue = useMemo(() => {
    let sum = 0;
    for (const p of selectedRows) {
      sum += p.rating * selected.get(p.id);
    }
    return sum;
  }, [selectedRows, selected]);

  const updateSelectedCount = (key, count) => {
    setSelected((prev) => {
      const next = new Map(prev);
      if (count) next.set(key, count);
      else next.delete(key);
      return next;
    });
  };

  const scrollToRow = (key) => {
    const container = resultsRef.current;
    if (!container) return;
    const el = container.querySelector(`[data-row-key="${CSS.escape(key)}"]`);
    if (!el) return;
    const top = el.offsetTop - container.clientHeight / 2;
    container.scrollTo({ top, behavior: "smooth" });
  };

  return (
    <Box
      sx={{
        mx: "auto",
        mt: 4,
        px: 2,
        display: "flex",
        gap: 2,
        alignItems: "flex-start",
        flexDirection: { xs: "column", md: "row" },
      }}
    >
      {/* Section 1: search */}
      <Box
        sx={{
          flex: 1,
          minWidth: 0,
          width: "100%",
          position: { md: "sticky" },
          top: { md: 16 },
        }}
      >
        <IconTabs value={tab} onChange={(_, v) => setTab(v)} />
        <TabPanel value={tab} index={0}>
          <SearchBar
            setData={setData}
            setLoading={setLoading}
            onToggleFilters={() => setFiltersOpen((o) => !o)}
          />
        </TabPanel>
        <TabPanel value={tab} index={1}>
          <ManualInput
            setData={setData}
            setLoading={setLoading}
            onToggleFilters={() => setFiltersOpen((o) => !o)}
          />
        </TabPanel>
        <FilterBuilder open={filtersOpen} />
        <Paper
          sx={{
            mt: 2,
            p: 2,
            display: "flex",
            flexDirection: "column",
            gap: 2,
          }}
        >
          {loading ? (
            <Box sx={{ mb: 2, display: "flex", justifyContent: "center" }}>
              <CircularProgress size={24} />
            </Box>
          ) : (
            <>
              <Typography variant="body1" color="text.secondary" align="center">
                Total rating: {formatNumber(totalRating, 3)}
              </Typography>
              <PokeChart results={results} />
            </>
          )}
        </Paper>
      </Box>

      {/* Section 2: sort + results */}
      <Box
        sx={{
          flex: 1,
          minWidth: 0,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          gap: 2,
          maxHeight: "calc(100vh - 32px)",
        }}
      >
        <SortBuilder />
        <Paper
          sx={{
            flex: 1,
            minWidth: 0,
            minHeight: 0,
            width: "100%",
            p: 2,
            pt: 1,
            display: "flex",
            flexDirection: "column",
          }}
        >
          <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1 }}>
            <Typography variant="subtitle1" fontWeight="bold">
              Pokemon
            </Typography>
            <Chip label={results.length} size="small" color="primary" />
          </Stack>
          <Divider />
          {loading && (
            <Box sx={{ mb: 2, display: "flex", justifyContent: "center" }}>
              <CircularProgress size={24} />
            </Box>
          )}

          <Box
            ref={resultsRef}
            sx={{
              flex: 1,
              minHeight: 0,
              overflow: "auto",
              pr: 0.5,
            }}
          >
            <Stack spacing={1}>
              {results.map((p) => {
                const key = p.id;
                const isSelected = selected.has(key);
                return (
                  <Paper
                    key={key}
                    data-row-key={key}
                    role="button"
                    tabIndex={0}
                    aria-pressed={isSelected}
                    onClick={() =>
                      updateSelectedCount(key, isSelected ? 0 : p.count)
                    }
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        updateSelectedCount(key, isSelected ? 0 : p.count);
                      }
                    }}
                    elevation={isSelected ? 3 : 1}
                    sx={{
                      overflow: "auto",
                      p: 2,
                      cursor: "pointer",
                      border: 2,
                      borderColor: isSelected ? "primary.main" : "transparent",
                      transition: (theme) =>
                        theme.transitions.create(
                          ["border-color", "box-shadow"],
                          {
                            duration: theme.transitions.duration.shorter,
                          },
                        ),
                    }}
                  >
                    <Typography fontWeight="bold">
                      {p.name} — Level {p.level}
                    </Typography>

                    <Box
                      component="img"
                      src={`https://pokemoncreed.net/sprites/${encodeURIComponent(
                        p.name,
                      )}.png`}
                      alt={p.name}
                      sx={{ height: 96, my: 1, pointerEvents: "none" }}
                    />

                    <Typography
                      component="div"
                      variant="body2"
                      sx={{
                        display: "grid",
                        gridTemplateColumns: "4ch 1ch 4ch minmax(0, 1fr)",
                        columnGap: 7,
                        alignItems: "baseline",
                        fontFamily: "monospace",
                        fontVariantNumeric: "tabular-nums",
                        whiteSpace: "nowrap",
                      }}
                    >
                      <Box component="span" sx={{ textAlign: "left" }}>
                        {formatNumber(p.rating)}
                      </Box>

                      <Box component="span" sx={{ textAlign: "left" }}>
                        <Tooltip
                          title={`(${p.male}M/${p.female}F/${p.ungendered}G)`}
                          placement="top"
                        >
                          x{p.count}
                        </Tooltip>
                      </Box>
                      <Box component="span" sx={{ textAlign: "left" }}>
                        {formatNumber(p.rating * p.count)}
                      </Box>
                      <Box component="span" sx={{ textAlign: "left" }}>
                        {p.total} /{" "}
                        {
                          <Box component="span" sx={{ textAlign: "left" }}>
                            <Tooltip
                              title={`(${p.rarity.male}M/${p.rarity.female}F/${p.rarity.ungendered}G)`}
                              placement="top"
                            >
                              {p.rarity.total}
                            </Tooltip>
                          </Box>
                        }{" "}
                        ({(p.percentage / 100).toFixed(2)}%)
                      </Box>
                    </Typography>
                  </Paper>
                );
              })}
            </Stack>
          </Box>
        </Paper>
      </Box>

      {/* Section 3: selected */}
      <Paper
        sx={{
          flex: 1,
          minWidth: 0,
          width: "100%",
          p: 2,
          pt: 1,
          position: { md: "sticky" },
          top: { md: 16 },
        }}
      >
        <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1 }}>
          <Typography variant="subtitle1" fontWeight="bold">
            Selected
          </Typography>
          <Chip label={selectedRows.length} size="small" color="secondary" />
        </Stack>
        {selectedRows.length === 0 ? (
          <Typography variant="body2" color="text.secondary">
            Click items in the list to add them here.
          </Typography>
        ) : (
          <>
            <TableContainer sx={{ maxHeight: "40vh" }}>
              <Table stickyHeader size="small" sx={{ fontFamily: "monospace" }}>
                <TableHead>
                  <TableRow>
                    <TableCell>Name</TableCell>
                    <TableCell align="right">Level</TableCell>
                    <TableCell align="right">Rate</TableCell>
                    <TableCell align="right">Count</TableCell>
                    <TableCell align="right">Total</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {selectedRows.map((p) => {
                    const key = p.id;
                    return (
                      <TableRow
                        key={key}
                        hover
                        onClick={() => scrollToRow(key)}
                        sx={{ cursor: "pointer" }}
                      >
                        <TableCell>{p.name}</TableCell>
                        <TableCell align="right">Level {p.level}</TableCell>
                        <TableCell align="right">
                          {formatNumber(p.rating)}
                        </TableCell>
                        <TableCell
                          align="right"
                          onClick={(e) => e.stopPropagation()}
                        >
                          {key === editingKey ? (
                            <Box
                              sx={{
                                display: "inline-flex",
                                alignItems: "center",
                                gap: 0.5,
                              }}
                            >
                              <TextField
                                autoFocus
                                size="small"
                                type="number"
                                slotProps={{
                                  htmlInput: {
                                    min: 1,
                                    max: p.count,
                                    style: {
                                      appearance: "textfield",
                                      MozAppearance: "textfield",
                                    },
                                  },
                                }}
                                sx={{
                                  "& input::-webkit-outer-spin-button, & input::-webkit-inner-spin-button":
                                    {
                                      WebkitAppearance: "none",
                                      margin: 0,
                                    },
                                }}
                                value={selected.get(key)}
                                onChange={(e) => {
                                  let val = parseInt(e.target.value, 10);
                                  if (val > p.count) val = p.count;
                                  if (val < 1 || isNaN(val)) val = 1;
                                  updateSelectedCount(key, val);
                                }}
                                onBlur={() => setEditingKey(null)}
                              />
                              <span>/ {p.count}</span>
                            </Box>
                          ) : (
                            <span
                              onClick={() => setEditingKey(key)}
                              style={{
                                borderBottom: "1px dashed #aaa",
                                cursor: "pointer",
                              }}
                            >
                              x{selected.get(key)}
                            </span>
                          )}
                        </TableCell>
                        <TableCell align="right">
                          {formatNumber(p.rating * selected.get(key))}
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </TableContainer>
            <Box
              sx={{
                pt: 2,
                borderTop: 1,
                borderColor: "divider",
                fontFamily: "monospace",
                fontVariantNumeric: "tabular-nums",
              }}
            >
              <Typography variant="body2">
                Total value: {formatNumber(totalSelectedValue, 3)}
              </Typography>
            </Box>
          </>
        )}
      </Paper>
    </Box>
  );
}

export default App;
