import { Switch, styled } from "@mui/material";

const ThemeSwitch = styled(Switch)(({ theme }) => ({
  width: 64,
  height: 36,
  padding: 0,
  position: "relative",

  // position the thumb dead-center vertically
  "& .MuiSwitch-switchBase": {
    padding: 0,
    margin: 0,
    top: "50%",
    left: 6,
    transform: "translateY(-50%)",
    transition: theme.transitions.create(["left", "right", "transform"], {
      duration: 200,
    }),
    "&.Mui-checked": {
      left: "auto",
      right: 6,
      transform: "translateY(-50%)",
      "& + .MuiSwitch-track": {
        backgroundColor: theme.palette.mode === "dark" ? "#8796A5" : "#aab4be",
        opacity: 1,
      },
    },
  },

  // perfect circular thumb with centered icon
  "& .MuiSwitch-thumb": {
    width: 24,
    height: 24,
    borderRadius: "50%",
    boxShadow: "none", // avoid “octagon” look from shadows
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    backgroundColor:
      theme.palette.mode === "dark"
        ? theme.palette.grey[200]
        : theme.palette.grey[800],
    "& svg": { fontSize: 16 }, // icon size inside the circle
  },

  // fully rounded track; same height as container for clean centering
  "& .MuiSwitch-track": {
    borderRadius: 18,
    height: "100%",
    opacity: 1,
    backgroundColor: theme.palette.mode === "dark" ? "#8796A5" : "#aab4be",
  },
}));

export default ThemeSwitch;
