import React from "react";
import Chart from "react-apexcharts";
import { useTheme } from "@mui/material/styles";
import { Variant } from "../constants";

export default function PokeChart({ results }) {
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";
  const textColor = theme.palette.text.primary;
  const strokeColor = theme.palette.background.paper;
  const categorizedTotals = results.reduce(
    (acc, p) => {
      const key = p.variant;
      if (!acc[key]) {
        acc[key] = 0;
      }
      acc[key] += p.rating * p.count;
      return acc;
    },
    Object.fromEntries(Object.values(Variant).map((key) => [key, 0])),
  );

  // Calculate the series and total value
  const series = Object.values(categorizedTotals);
  const totalValue = series.reduce((a, b) => a + b, 0);

  // Generate a key based on categorizedTotals to force re-render
  const chartKey = Object.entries(categorizedTotals)
    .map(([key, value]) => `${key}-${value}`)
    .join("_");

  const options = {
    chart: {
      background: "transparent",
      toolbar: { show: false },
      animations: {
        enabled: true,
        easing: "easeinout",
        speed: 800,
        animateGradually: { enabled: true, delay: 150 },
      },
    },
    labels: Object.keys(categorizedTotals),
    colors: [
      "#D3D3D3",
      "#b71515",
      "#808080",
      "#ffc107",
      "#2de7e0",
      "#28a745",
      "#573c9c",
    ],
    legend: {
      show: true,
      position: "bottom",
      fontSize: "14px",
      labels: { colors: [textColor] },
      markers: { width: 10, height: 10, radius: 5 },
      itemMargin: { horizontal: 10, vertical: 5 },
    },
    dataLabels: {
      enabled: true,
      formatter: (val) => val.toLocaleString(),
      dropShadow: {
        enabled: false,
      },
      style: {
        fontSize: "14px",
        fontWeight: "600",
        colors: [textColor],
      },
      background: {
        enabled: false,
      },
    },
    tooltip: {
      theme: isDark ? "dark" : "light",
      y: { formatter: (val) => val.toLocaleString() },
      style: { fontSize: "14px" },
    },
    stroke: {
      show: true,
      width: 2,
      colors: [strokeColor],
    },
    plotOptions: {
      pie: {
        expandOnClick: true,
        donut: {
          size: "70%",
          labels: {
            show: true,
            name: {
              show: true,
              fontSize: "18px",
              fontWeight: "bold",
              color: textColor,
            },
            value: {
              show: true,
              fontSize: "22px",
              fontWeight: "bold",
              color: textColor,
              formatter: (val) => {
                return Number(val).toLocaleString();
              },
            },
            total: {
              show: true,
              label: "Total",
              color: textColor,
              fontSize: "18px",
              fontWeight: "bold",
              formatter: () => {
                return totalValue.toLocaleString();
              },
            },
          },
        },
      },
    },
    responsive: [
      {
        breakpoint: 768,
        options: {
          chart: {
            height: 300,
          },
          legend: {
            position: "bottom",
            fontSize: "12px",
          },
          dataLabels: {
            style: {
              fontSize: "12px",
            },
          },
          plotOptions: {
            pie: {
              donut: {
                labels: {
                  name: {
                    fontSize: "14px",
                  },
                  value: {
                    fontSize: "16px",
                  },
                  total: {
                    fontSize: "14px",
                  },
                },
              },
            },
          },
        },
      },
    ],
  };

  return (
    <Chart
      key={chartKey}
      options={options}
      series={series}
      type="donut"
      height={380}
    />
  );
}
