import { useSearchParams } from "react-router-dom";
import { useMemo, useCallback } from "react";
import { v4 as uuid } from "uuid";
import { filterConfigs } from "../constants";
import { digestResults } from "../utils";

const EMPTY_SELECTED = new Map();

function encodeFilters(filters) {
  if (!filters?.length) return "";

  return filters
    .filter((f) => f.field && f.operator && f.value != null)
    .map((f) => {
      let value = f.value;

      if (Array.isArray(value)) {
        value = value.join("|");
      }

      return `${f.field}.${f.operator}.${encodeURIComponent(value)}`;
    })
    .join(",");
}

function decodeFilters(str) {
  if (!str) return [];

  const filters = str.split(",").map((part) => {
    const [field, operator, rawValue] = part.split(".");

    let value = decodeURIComponent(rawValue ?? "");

    if (filterConfigs.find((c) => c.key === field)?.type === "enum") {
      value = value.split("|").filter(Boolean);
    } else if (!isNaN(value) && value.trim() !== "") {
      value = Number(value);
    }

    return {
      id: uuid(),
      field,
      operator,
      value,
    };
  });

  return filters;
}

function encodeSort(sort) {
  if (!sort?.length) return "";
  return sort.map((s) => `${s.field}.${s.direction}`).join(",");
}

function decodeSort(str) {
  if (!str) return [];
  return str.split(",").map((part) => {
    const i = part.lastIndexOf(".");
    const [field, direction] =
      i < 0 ? [part, ""] : [part.slice(0, i), part.slice(i + 1)];
    return { field, direction: Number(direction) || 1 };
  });
}

function encodeSelected(selected) {
  if (!selected || selected.size === 0) return "";

  return Array.from(selected.entries())
    .map(([id, count]) => `${id}.${count}`)
    .join(",");
}

function decodeSelected(str) {
  if (!str) return EMPTY_SELECTED;

  const map = new Map();
  for (const part of str.split(",")) {
    const i = part.lastIndexOf(".");
    if (i < 0) continue;

    const id = part.slice(0, i);
    const count = Number(part.slice(i + 1));
    if (!id || !Number.isFinite(count) || count <= 0) continue;
    map.set(id, count);
  }
  return map.size === 0 ? EMPTY_SELECTED : map;
}

/**
 * @param {Array} [data]
 */
export function useURLParams(data) {
  const [params, setParams] = useSearchParams();

  const filters = useMemo(() => decodeFilters(params.get("filters")), [params]);
  const sort = useMemo(() => decodeSort(params.get("sort")), [params]);
  const usernames = useMemo(() => params.get("usernames") ?? "", [params]);

  const dataDigest = useMemo(() => digestResults(data), [data]);
  const selected = useMemo(() => {
    if (!dataDigest) return EMPTY_SELECTED;
    if (params.get("token") !== dataDigest) return EMPTY_SELECTED;
    return decodeSelected(params.get("selected"));
  }, [params, dataDigest]);

  const updateParam = useCallback(
    (key, value) => {
      const next = new URLSearchParams(params);

      let encoded;
      if (key === "filters") encoded = encodeFilters(value);
      else if (key === "sort") encoded = encodeSort(value);
      else encoded = value;

      if (encoded == null || encoded === "") {
        next.delete(key);
      } else {
        next.set(key, encoded);
      }

      setParams(next);
    },
    [params, setParams],
  );

  const setSelected = useCallback(
    (updater) => {
      if (!dataDigest) return;

      const nextSelected =
        typeof updater === "function" ? updater(selected) : updater;

      const next = new URLSearchParams(params);
      const encoded = encodeSelected(nextSelected);
      if (encoded) {
        next.set("selected", encoded);
        next.set("token", dataDigest);
      } else {
        next.delete("selected");
        next.delete("token");
      }
      setParams(next);
    },
    [params, selected, dataDigest, setParams],
  );

  return {
    filters,
    sort,
    usernames,
    selected,
    setFilters: (v) => updateParam("filters", v),
    setSort: (v) => updateParam("sort", v),
    setUsernames: (v) => updateParam("usernames", v),
    setSelected,
  };
}
